import data from './showcase-data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={problem:'研究問題',method:'方法',result:'成果',limitation:'限制與適用條件'};
function citation(c){const paper=data.papers.find(p=>p.id===c.paperId);return `<details class="showcase-citation"><summary>${esc(paper.title)} · PDF p.${c.page}</summary><blockquote>${esc(c.quote)}</blockquote><a href="${esc(paper.pdf)}#page=${c.page}" target="_blank" rel="noopener noreferrer">開啟原文此頁 ↗</a></details>`}
function claim(c){return `<article class="claim"><span class="badge ${c.kind==='evidence'?'green':''}">${c.kind==='evidence'?'原文整理':'推論／建議'}</span><h3>${esc(labels[c.section]||c.section)}</h3><p>${esc(c.text)}</p>${c.citations.map(citation).join('')}</article>`}
export function showcaseHTML(){return `<section class="hero"><div><span class="badge green">公開研究庫 · 已完成重點摘要</span><h1>${esc(data.name)}</h1><p>${esc(data.affiliation)}</p></div></section><section class="panel"><p>一階最佳化、巢狀隨機最佳化與受限雙層決策。</p><div class="actions"><a class="button" href="#public-papers">閱讀 4 篇論文分析 ↓</a><a class="button" href="#public-overview">研究概要 ↓</a><button class="primary" data-act="import-folder">建立自己的研究庫</button><button data-act="connect">開啟既有研究庫</button></div><details style="margin-top:16px"><summary>資料來源與範圍</summary><p>${esc(data.provenance)}</p><p>${esc(data.scope)}</p><p>公開資料唯讀；瀏覽不需金鑰，不會呼叫 API，也不寫入你的本機資料夾。</p></details></section><section class="panel" id="public-overview"><h2>跨論文研究概要</h2>${data.overview.map(claim).join('')}</section><section id="public-papers"><h2>論文與逐篇分析</h2>${data.papers.map(p=>`<details class="panel"><summary><strong>${esc(p.title)}</strong><br><small>${esc(p.version)} · ${p.pageCount} 頁 · 摘要已整理</small></summary><p><a href="${esc(p.pdf)}" target="_blank" rel="noopener noreferrer">閱讀完整 PDF ↗</a></p>${p.note?`<p class="hint">${esc(p.note)}</p>`:''}${p.claims.map(claim).join('')}</details>`).join('')}</section><p class="hint">引文以 PDF 實際頁次標示；已核對文字出處，結論仍需人工判讀。</p>`}
